    const spot = REST_SPOTS[game.location];
    if (!spot) return;
    if (game[spot.key] === game.day) { toast('You have already rested here today.'); return; }
    game[spot.key] = game.day;
    restCrewFully();
    logEvent(spot.log, 'good');
    if (typeof updateUI === 'function') updateUI();
